from collections import Counter

# Training text: each word is a tuple of characters, with its frequency
words = {tuple("low"): 3, tuple("lower"): 1, tuple("lowest"): 1}
print("words:", {"".join(w): n for w, n in words.items()})

def merge(word, pair):
    out, i = [], 0
    while i < len(word):
        if i + 1 < len(word) and (word[i], word[i + 1]) == pair:
            out.append(word[i] + word[i + 1])  # glue the pair into one symbol
            i += 2
        else:
            out.append(word[i])
            i += 1
    return tuple(out)

for step in range(1, 5):
    pairs = Counter()
    for w, n in words.items():
        for a, b in zip(w, w[1:]):
            pairs[(a, b)] += n          # count adjacent pairs, weighted by frequency
    best = pairs.most_common(1)[0][0]   # most frequent pair becomes a new token
    words = {merge(w, best): n for w, n in words.items()}
    print("merge", step, best, "->", [list(w) for w in words])
# Each round is O(total symbols); vocabulary grows by one token per merge

# Toy "model": a lookup table giving the next token (greedy decoding)
NEXT = {"the": "cat", "cat": "sat", "sat": "on", "on": "the", "<s>": "the"}

def generate(prompt, steps, use_cache):
    tokens = list(prompt)
    cache = []        # stands in for the KV cache: one entry per processed token
    work = 0          # how many token positions we had to process
    if use_cache:
        cache = list(tokens); work += len(tokens)      # prefill: whole prompt at once
    for _ in range(steps):
        if use_cache:
            nxt = NEXT[tokens[-1]]
            work += 1                                   # only the new token is processed
        else:
            work += len(tokens)                         # reprocess everything each step
            nxt = NEXT[tokens[-1]]
        tokens.append(nxt)                              # output feeds back as input
        if use_cache:
            cache.append(nxt)
    return tokens, work

prompt = ["<s>", "the", "cat", "sat"]
for flag in (False, True):
    toks, work = generate(prompt, 6, flag)
    print("cache" if flag else "no cache", "->", " ".join(toks), "| positions processed:", work)
# Without cache work grows ~ n^2 over the run; with cache it is ~ n

import math

logits = {"the": 4.0, "a": 3.0, "cat": 2.0, "dog": 1.0, "xylophone": -1.0}

def softmax(lg, temp):
    exps = {t: math.exp(v / temp) for t, v in lg.items()}  # temperature divides logits
    s = sum(exps.values())
    return {t: e / s for t, e in exps.items()}

def show(title, p):
    print(title.ljust(18), {t: round(x, 3) for t, x in p.items()})

def top_k(p, k):
    keep = dict(sorted(p.items(), key=lambda kv: -kv[1])[:k])   # keep k best
    s = sum(keep.values()); return {t: x / s for t, x in keep.items()}

def top_p(p, mass):
    keep, total = {}, 0.0
    for t, x in sorted(p.items(), key=lambda kv: -kv[1]):
        keep[t] = x; total += x
        if total >= mass: break            # smallest set reaching the mass
    s = sum(keep.values()); return {t: x / s for t, x in keep.items()}

show("temp 0.5", softmax(logits, 0.5))
show("temp 1.0", softmax(logits, 1.0))
show("temp 2.0", softmax(logits, 2.0))
base = softmax(logits, 1.0)
show("top-k 2", top_k(base, 2))
show("top-p 0.9", top_p(base, 0.9))
print("greedy pick:", max(logits, key=logits.get))
